/* Does this registration belong to an AgentX subagent?
 *
 * netsnmp_subtree_find() returning non-NULL does NOT mean the OID belongs to
 * a subagent -- a hit on our own registration answers locally and still looks
 * like success. That gap is what let the GET-forward path be believed broken
 * for two rounds (ADR-0030), and it is the only thing standing between a
 * mis-specified probe and a request forwarded to the wrong place.
 *
 * This used to ask the negative question ("is it one of ours?") and forward to
 * anything that was not. That is not the same question: every other handler in
 * the process -- a net-snmp built-in MIB module, a dlmod plugin -- passed it
 * too, answered synchronously, and the value was gone with no error and no
 * packet on the wire. mxlldp/ lost all 25 varbinds that way (2026-08-14).
 *
 * The positive test is a function-pointer comparison: master_admin.c:223
 * registers every subagent subtree with agentx_master_handler as its access
 * method, and master_admin.c:232 hangs the subagent's netsnmp_session off
 * handler->myvoid. Handler injection does not disturb it --
 * netsnmp_inject_handler_before() prepends, and inject_handler_into_subtree()
 * inserts into a duplicate -- so walking the chain finds the original node.
 *
 * Walk the chain rather than testing reginfo->handler directly, for the same
 * reason as before: MIB_HANDLER_AUTO_NEXT wrappers mean the node of interest
 * is not always the first link. */
static int mox_snmp_reg_is_agentx (netsnmp_handler_registration *reginfo)
{
    netsnmp_mib_handler *h;

    if ( reginfo == NULL )
    {
        return 0;
    }
    for ( h = reginfo->handler; h != NULL; h = h->next )
    {
        if ( h->access_method == agentx_master_handler )
        {
            return 1;
        }
    }
    return 0;
}

