static struct mox_agentx_probe gAgentXDerived[AGENTX_OWNED_MAX];
static signed char             gAgentXDerivedState[AGENTX_OWNED_MAX];
                                    /* 0 = not tried, 1 = derived, -1 = none */

/* How far up the walk may go: the group's own OID root, taken as the longest
 * common prefix of every entry the list line covers, accumulated during
 * registration (mox_snmp_root_note_entry). Without it the walk ran to
 * .1.3.6 and could leave the group's MIB altogether.
 *
 * A floor is not redundant with the subagent test above. That test only says
 * "some subagent owns this"; land on another subagent, or on another MIB root
 * of the same one, and the request really is delegated, the answer really does
 * come back asynchronously, and it is noSuchObject -- too late for any check
 * this file can make. Staying inside the group's own root is the only thing
 * that keeps the target plausible. */
static oid gAgentXRoot[AGENTX_OWNED_MAX][IES_MAX_OID];
static int gAgentXRootLen[AGENTX_OWNED_MAX];    /* 0 = no entry seen yet */

static void mox_snmp_root_note_entry (struct ies_auto_mibs_entry *entry,
                                      int                         prefix_idx)
{
    int i;
    int n;

    if ( prefix_idx < 0 || prefix_idx >= AGENTX_OWNED_MAX ||
         entry->oid_len <= 0 || entry->oid_len > IES_MAX_OID )
    {
        return;
    }
    if ( gAgentXRootLen[prefix_idx] == 0 )
    {
        memcpy(gAgentXRoot[prefix_idx], entry->oid_list,
               sizeof(oid) * (size_t) entry->oid_len);
        gAgentXRootLen[prefix_idx] = entry->oid_len;
        return;
    }

    n = ( entry->oid_len < gAgentXRootLen[prefix_idx] )
            ? entry->oid_len : gAgentXRootLen[prefix_idx];
    for ( i = 0; i < n; i++ )
    {
        if ( gAgentXRoot[prefix_idx][i] != entry->oid_list[i] )
        {
            break;
        }
    }
    gAgentXRootLen[prefix_idx] = i;
}

