static int gAgentXRootLen[AGENTX_OWNED_MAX];    /* 0 = no entry seen yet */

static void mox_snmp_root_note_entry (struct ies_auto_mibs_entry *entry,
                                      int                         prefix_idx)
{
    int i;
    int n;

    if ( prefix_idx < 0 || prefix_idx >= AGENTX_OWNED_MAX ||
         entry->oid_len <= 0 || entry->oid_len > IES_MAX_OID )
    {
        return;
    }
    if ( gAgentXRootLen[prefix_idx] == 0 )
    {
        memcpy(gAgentXRoot[prefix_idx], entry->oid_list,
               sizeof(oid) * (size_t) entry->oid_len);
        gAgentXRootLen[prefix_idx] = entry->oid_len;
        return;
    }

    n = ( entry->oid_len < gAgentXRootLen[prefix_idx] )
            ? entry->oid_len : gAgentXRootLen[prefix_idx];
    for ( i = 0; i < n; i++ )
    {
        if ( gAgentXRoot[prefix_idx][i] != entry->oid_list[i] )
        {
            break;
        }
    }
    gAgentXRootLen[prefix_idx] = i;
}

