    /* Only ever hand a request to an AgentX subagent. Anything else answers
     * synchronously and reports success, which is indistinguishable from a
     * real forward and silently costs the value. Refusing makes the caller
     * fall through to the local read, so the worst case of a bad probe is
     * "no speed-up", never a wrong or lost value. */
    if ( !mox_snmp_reg_is_agentx(iss_sub->reginfo) )
    {
        MOX_GETFWD_TRACE(
            "GETFWD T3 NOTAGENTX: probe_oid=%s resolved to a non-subagent "
            "registration (handlerName=%s), refusing to forward\n",
            mox_snmp_getfwd_oid_str(probe_oid, probe_oid_len,
                                    oidbuf, sizeof(oidbuf)),
            (iss_sub->reginfo->handlerName != NULL)
                ? iss_sub->reginfo->handlerName : "(null)");
        return -1;
    }

    /* An AgentX registration can still answer synchronously with an error --
     * agentx_master_handler (master.c:458) does exactly that when its session
     * pointer is NULL. Snapshot what a failed forward would dirty so the
     * fall-through starts from a clean request: _request_set_error()
     * (snmp_agent.c:3967) sets processed, delegated, status, and for the
     * exception values requestvb->type. Leaving the error status behind would
     * make the local read produce the right value inside a failed PDU. */
    saved_processed = request->processed;
    saved_status    = request->status;
    saved_vb_type   = (request->requestvb != NULL) ? request->requestvb->type
                                                   : (u_char) ASN_NULL;

    /* Forward only THIS request; detach siblings so netsnmp_call_handlers does
     * not pull the rest of the chain (this handler is invoked per request). */
    saved_next    = request->next;
    request->next = NULL;
    (void) netsnmp_call_handlers(iss_sub->reginfo, reqinfo, request);
    request->next = saved_next;

    /* Which half of the outcome this is decides whether the varbind may be
     * read at all. The master marks the request delegated before sending
     * (master.c:238,280) and clears it when the reply arrives (:355,399,420),
     * so at this point:
     *
     *   delegated set  -> really went to AgentX, answer arrives later. The
     *                     varbind is empty and MUST NOT be judged; a
     *                     noSuchObject from the subagent is out of reach here.
     *   delegated 0    -> answered synchronously, so whatever the answer is,
     *                     it is already in the request and can be judged.
     *
     * Only the second half is actionable, and it is the half that was losing
     * values. */
    if ( request->delegated == REQUEST_IS_NOT_DELEGATED &&
         !mox_snmp_request_has_answer(request) )
    {
        MOX_GETFWD_TRACE(
            "GETFWD T3 SYNCFAIL: probe_oid=%s answered synchronously with "
            "status=%d type=0x%02x, falling back to local read\n",
            mox_snmp_getfwd_oid_str(probe_oid, probe_oid_len,
                                    oidbuf, sizeof(oidbuf)),
            request->status,
            (request->requestvb != NULL) ? request->requestvb->type : 0);

        request->processed = saved_processed;
        request->delegated = REQUEST_IS_NOT_DELEGATED;
        request->status    = saved_status;
        if ( request->requestvb != NULL )
        {
            request->requestvb->type = saved_vb_type;
        }
        return -1;
    }

    return 0;
}

