/* Did a synchronous return leave a usable answer in the request? Anything else
 * -- an error status, an untouched varbind, an SNMP exception -- means the
 * forward produced nothing, and the local read is still worth doing. */
static int mox_snmp_request_has_answer (netsnmp_request_info *request)
{
    if ( request->status != SNMP_ERR_NOERROR || request->requestvb == NULL )
    {
        return 0;
    }
    switch ( request->requestvb->type )
    {
    case ASN_NULL:                      /* nobody wrote a value */
    case SNMP_NOSUCHOBJECT:
    case SNMP_NOSUCHINSTANCE:
    case SNMP_ENDOFMIBVIEW:
        return 0;
    default:
        return 1;
    }
}

