    (void) handler;
    (void) reginfo;

    if (reqinfo->mode == MODE_GET) {
        value = write_dump();
        snmp_set_var_typed_value(requests->requestvb, ASN_INTEGER,
                                 (u_char *) &value, sizeof(value));
    }
